// Soft-landing sites (landers, Apollo LM descent stages) measured on LROC NAC images.
// Data: landingSites.json, generated by scripts/build_landing_sites.py from the LROC "Anthropogenic
// Objects" table (Wagner et al. 2017, Icarus 283; source date in the file). Planetocentric
// latitude, east-positive longitude in degrees, Mean Earth / Polar Axis — the globe's convention.

import { haversineKm } from "./geo";
import data from "./landingSites.json";

export interface LandingSite {
  id: string;
  mission: string;
  vehicle: string | null;
  crewed: boolean;
  lat: number;
  lon: number;
  uncertainty_m: number;
  date_utc: string;
  coord_source: string;
}

export const LANDING_SITES: readonly LandingSite[] = data.sites;
export const LANDING_SOURCE = { citation: data.citation, url: data.url, updated: data.source_updated };

/** Closest site within maxKm of (lat, lon), with its distance; null if none. */
export function nearestLandingSite(lat: number, lon: number, maxKm: number): { site: LandingSite; distanceKm: number } | null {
  let best: { site: LandingSite; distanceKm: number } | null = null;
  for (const site of LANDING_SITES) {
    const d = haversineKm(lat, lon, site.lat, site.lon);
    if (d <= maxKm && (!best || d < best.distanceKm)) best = { site, distanceKm: d };
  }
  return best;
}

/** One-line label, e.g. "Apollo 11 (Eagle) · landed 1969-07-20". */
export function landingLabel(s: LandingSite): string {
  const key = (t: string) => t.toLowerCase().replace(/[^a-z0-9]/g, ""); // "Luna-16" ≡ "Luna 16"
  const [m, v] = [key(s.mission), key(s.vehicle ?? "")];
  const vehicle = v && !m.includes(v) && !v.includes(m) ? ` (${s.vehicle})` : "";
  return `${s.mission}${vehicle} · landed ${s.date_utc}`;
}
